import{_ as o,l as i,o as e,c as n,v as t,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"缓冲池 LRU-K / 2Q","description":"","frontmatter":{"title":"缓冲池 LRU-K / 2Q","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buffer-pool-lru-k.md","filePath":"cs/buffer-pool-lru-k.md","lastUpdated":1789023840000}'),E={name:"cs/buffer-pool-lru-k.md"};function c(A,a,u,_,m,f){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="缓冲池-lru-k-2q" tabindex="-1">缓冲池 LRU-K / 2Q <a class="header-anchor" href="#缓冲池-lru-k-2q" aria-label="Permalink to &quot;缓冲池 LRU-K / 2Q&quot;">​</a></h1><div class="epigraph"><p>一次扫描污染 LRU：顺序页只有一次命中却把热点挤出。LRU-K 看第 K 次最近访问时间，2Q 把第一次与多次访问分队列。</p><footer>—— 据 O&#39;Neil, O&#39;Neil and Weikum, LRU-K, SIGMOD 1993；Johnson and Shasha, 2Q；Gray and Reuter</footer></div><p>执行引擎在<a href="/cs/late-materialization">延迟物化</a>封口，gather 会打页。本课打开存储进阶：主干缓冲与脏页在 WAL 前已承认池的存在，替换策略往往一笔带过。缺口是扫描污染与「相关引用」：经典 LRU 把刚扫过的一次性页当成热点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OLTP 热点页应常驻；OLAP 大扫描应走过去几乎不留。LRU 把最近触摸的页放头，扫描让池充满一次性页，随后点查全 miss。缺口是<strong>用访问历史区分扫描与循环热点</strong>，不是再定义页。</p><p>LRU-K：记录每页最近 K 次访问时间，替换「第 K 次访问最久远」的页（K=2 常用）。一次扫描只有一次访问，第 2 次时间是 \\(-\\infty\\)，优先被换。2Q：A1 队列收第一次入池页，很快淘汰；第二次命中晋升到 Am（常 LRU）。时钟算法是近似，本课点名。</p><p><span class="marginnote">O&#39;Neil, O&#39;Neil, Weikum，SIGMOD 1993。Johnson and Shasha 2Q。与操作系统页替换同构，但数据库知道扫描、预取、脏页刷盘约束，不能直接套 OS LRU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>池：固定帧，每帧一页（或更大块）。命中：更新该页历史。未命中：按策略选牺牲者；若脏则先写（与 steal 策略、WAL 的 pageLSN 一致）。pin 下一课：正在用的页不能换。</p><p>预取：顺序扫描可提前读，策略应避免预取页立刻升成热点。中间结果临时页可标快速逐出。</p>',10)),(e(),s(h,null,{default:r(()=>[d(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%E9%A1%B5%22%5D%20--%3E%20K%5B%22%E6%9B%B4%E6%96%B0%E6%9C%80%E8%BF%91%20K%20%E6%AC%A1%E6%97%B6%E9%97%B4%22%5D%0A%20%20K%20--%3E%20VIC%5B%22%E7%89%BA%E7%89%B2%E7%AC%AC%20K%20%E6%AC%A1%E6%9C%80%E6%97%A7%22%5D%0A%20%20SCAN%5B%22%E9%A1%BA%E5%BA%8F%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20ONCE%5B%22%E5%8F%AA%E6%9C%89%E4%B8%80%E6%AC%A1%E8%AE%BF%E9%97%AE%22%5D%0A%20%20ONCE%20--%3E%20OUT%5B%22%E4%BC%98%E5%85%88%E6%8D%A2%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价模型假设的缓存命中率来自这套策略。校准若假定命中、策略却被扫描污染，DP 会错。并行工人争同一池，latch 保护替换结构——再下一课 latch。</p><p>脏页写回：替换要写，延长 miss 路径；后台刷脏与检查点互动，恢复课再接。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 pin 计数与 latch 区别。也不把 OS page cache 与库缓冲池双缓存当推荐——库常用 <code>O_DIRECT</code>。LRU-K 的历史表本身占内存，K 与精度是调参。</p><p>后课默认：替换要抗扫描污染；热点靠第二次及以后访问识别。pin 与 latch：页被固定时不能成牺牲者，并发要用短锁。</p><p>策略服务的是命中率，不服务可串行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LRU-K / 2Q 区分一次性扫描与多次热点。</li><li>脏牺牲者先写；正在使用的页必须 pin。</li><li>pin 与 latch 下一课：固定与互斥不是同一把锁。</li><li>出处：O&#39;Neil et al. LRU-K；Johnson and Shasha 2Q；Gray and Reuter。</li></ul>',9))])}const L=o(E,[["render",c]]);export{C as __pageData,L as default};
